function updateHUD(){music.report();const n=NODES[state.collected.length],nav=navigationTarget(),target=nav.pos;const dist=player.pos.distanceTo(target);projected.copy(target).project(camera);const behind=target.clone().sub(camera.position).dot(camera.getWorldDirection(new T.Vector3()))<0;let sx=(projected.x*.5+.5)*innerWidth,sy=(-projected.y*.5+.5)*innerHeight;if(behind){const dir=target.clone().sub(camera.position);const angle=Math.atan2(-dir.x,-dir.z)-player.yaw;sx=Math.sin(angle)>0?20:innerWidth-20;sy=innerHeight*.48;}sx=Math.max(75,Math.min(innerWidth-75,sx));sy=Math.max(180,Math.min(innerHeight-180,sy));$('#waypoint').style.left=`${sx}px`;$('#waypoint').style.top=`${sy}px`;$('#waypoint').style.opacity=senseUntil>state.elapsed?'1':'.72';$('#waypoint span').textContent=behind?'‹':'◇';$('#distance').textContent=`${nav.name} · ${Math.ceil(dist)} m`;$('#interact').hidden=!canInteract();$('#action-label').textContent=n?'Weave and cross':'Find the other spider';if(n?.id==='window'&&birdBlocking(music.clock(state.elapsed)))$('#action-label').textContent='Wait for the bird to pass';$('#clock').textContent=`${formatTime(cycleAt(music.clock(state.elapsed)))} / 3:49`;$('#cycle-fill').style.width=`${cycleAt(music.clock(state.elapsed))/229*100}%`;$('#game-state').textContent=JSON.stringify({phase:state.phase,collected:state.collected,position:player.pos.toArray().map(n=>+n.toFixed(2)),yaw:+player.yaw.toFixed(2),elapsed:Math.round(state.elapsed),travel:!!travel,canInteract:canInteract(),rescues:state.rescues});}
